),
products AS (
  INSERT INTO public.products
    (name, slug, description, brand_id, category_id, mrp_paise, price_paise, unit_label,
     stock, low_stock_threshold, images, tags, rating, is_active)
  SELECT d.name, d.slug, '', b.id, COALESCE(c.id, p.id), d.mrp_paise, d.price_paise,
    d.unit_label, d.stock, 10, d.images, '{}'::text[], 0, true
  FROM product_data d
  CROSS JOIN brand b
  JOIN parents p ON p.slug='msg-import-' || d.parent_slug
  LEFT JOIN children c ON c.slug=d.category_slug
  ON CONFLICT (slug) DO NOTHING
  RETURNING id, slug
)
SELECT
  (SELECT count(*) FROM products) AS products_inserted,
  (SELECT count(*) FROM parents) AS parent_categories_handled,
  (SELECT count(*) FROM children) AS child_categories_handled,
  (SELECT count(*) FROM brand) AS brand_handled;
